window.WWG_LOGO_FALLBACK = "data:image/png;base64,";
window.WWGUseLogoFallback = function useWalkWithGodLogoFallback(img) {
  if (!img || !window.WWG_LOGO_FALLBACK || img.dataset.logoFallbackApplied === "true") {
    return false;
  }
  img.dataset.logoFallbackApplied = "true";
  img.onerror = null;
  img.src = window.WWG_LOGO_FALLBACK;
  return true;
};